                                .tooltip("Send Next sprint now")
                                .on_click(cx.listener(|this, _, _, cx| this.start_now(cx))),
                        ),
                )
                .into_any_element(),
            );
        }
        // Why the next sprint isn't starting by itself, in its heading.
        if section == Section::Next
            && let Some(why) = self.auto_held(cx)
        {
            actions.insert(
                0,
                gpui_kit::TestSupportExt::test_support(
                    div()
                        .id("planning-auto-start-held")
                        .min_w_0()
                        .truncate()
                        .text_xs()
                        .text_color(warning)
                        .child(why),
                )
                .into_any_element(),
            );
        }
        let name = div().text_sm().font_semibold().child(section.label());
        let heading = if section == Section::Done {
            // Collapsed until opened, from its heading.
            gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-done-toggle")
                    .track_focus(&self.done_focus)
                    .gap_2()
                    .px_1()
                    .items_center()
                    .rounded(theme.radius)
                    .border_1()
                    .border_color(gpui_kit::transparent_black())
                    .focus(|toggle| toggle.border_color(theme.ring))
                    .cursor_pointer()
                    .text_color(muted)
