                        .child(format!("{paused} paused")),
                )
            })
            .child(div().flex_1())
            .children(actions)
            .into_any_element()
    }

    fn render_section(
        &mut self,
        section: Section,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let heading = self.render_heading(section, cx);
        let mut column = v_flex()
            .w_full()
            .gap(ROW_GAP)
            .track_focus(&self.section_focus[section.key()])
            .child(div().pb(HEADING_GAP - ROW_GAP).child(heading));
        // While the plan is read: skeleton rows, never an empty section.
        if !self.loaded && section != Section::Done {
            if section == Section::Next
                && let Some(why) = self.load_error.clone()
            {
                column = column.child(gpui_kit::TestSupportExt::test_support(
                    h_flex()
                        .id("planning-load-error")
                        .gap_2()
                        .items_center()
                        .child(div().flex_1().text_sm().text_color(theme.danger).child(why))
                        .child(
                            Button::new("planning-load-retry")
                                .ghost()
                                .xsmall()
                                .label("Try again")
                                .tooltip("Read the plan again")
                                .on_click(cx.listener(|this, _, _, cx| this.read_again(cx))),
                        ),
                ));
            } else {
                column = column.child(gpui_kit::TestSupportExt::test_support(
                    v_flex()
                        .id(SharedString::from(format!(
                            "planning-loading-{}",
                            section.key()
                        )))
                        .gap(ROW_GAP)
                        .child(skeleton_row(cx))
                        .child(skeleton_row(cx)),
                ));
            }
            return column.into_any_element();
        }
        let about = self.panel_about();
        let panel_wanted = self.drafting.is_some() || !self.proposals.is_empty();
        if section == Section::Backlog && panel_wanted && about.is_none() {
            // Proposals kept from before come back in their panel.
            if self.drafting.is_none() {
                self.open_draft_panel(None, false, window, cx);
            }
            column = column.child(self.render_draft_panel(window, cx));
        }
        if section == Section::Done && !self.done_expanded {
            return column.into_any_element();
        }
        let gap = self.gap.get();
        let count = self.sections[section_ix(section)].len();
        if count == 0 {
            // Lets UI tests find the empty state; inert in normal builds.
            column = column.child(gpui_kit::TestSupportExt::test_support(
                self.drop_zone(
                    section,
                    0,
                    div().id(SharedString::from(format!(
                        "planning-empty-{}",
                        section.key()
                    ))),
                    cx,
                )
                .child(empty_line(section.empty(), muted)),
            ));
        }
        for ix in 0..count {
            let name = self.sections[section_ix(section)][ix].name.clone();
            let open = self.open.as_ref().is_some_and(|open| open.name == name);
            let row = self.render_row(section, ix, open, gap, window, cx);
            column = column.child(row);
            // A sent story's steps beneath it: in Current sprint always,
            // in Done collapsed to their count until expanded.
            if !open {
                let listed = match section {
                    Section::Current => self.render_story_steps(&name, None, cx),
                    Section::Done => {
                        self.render_story_steps(&name, Some(format!("done:{name}")), cx)
                    }
                    _ => None,
                };
                column = column.children(listed);
            }
            if open {
                let steps = self.story(&name).map_or(0, |story| story.steps().len());
                for at in 0..steps {
                    self.step_focus(&name, at, cx);
                }
                let cited = self.story(&name).map_or(0, |story| story.spec.len());
                for at in 0..cited {
                    self.row_focus(&format!("cite:{name}:{at}"), cx);
                }
                column = column.child(self.render_open(&name, window, cx));
                if let Some(findings) = self.render_findings(Some(&name), window, cx) {
                    column = column.child(div().pl(px(28.)).child(findings));
                }
            }
            if panel_wanted && about.as_deref() == Some(name.as_str()) {
                if self.drafting.is_none() {
                    self.open_draft_panel(Some(name.clone()), false, window, cx);
                }
                column = column.child(self.render_draft_panel(window, cx));
            }
        }
        if section == Section::Next {
            let new_story = self
                .drop_zone(
                    section,
                    count,
                    h_flex()
                        .id(SharedString::from(format!(
                            "planning-new-story-{}",
                            section.key()
                        )))
                        .h(px(28.))
                        .px_3()
                        .gap_2()
                        .items_center()
                        .rounded(theme.radius)
                        .cursor_pointer()
                        .text_sm()
                        .text_color(muted)
                        .aria_label("New story")
                        .tooltip(move |window, cx| {
                            gpui_kit::component::tooltip::Tooltip::new(format!(
                                "Add a story here ({MOD}N)"
                            ))
                            .build(window, cx)
                        })
                        .hover(|row| row.bg(theme.list_hover)),
                    cx,
                )
                .on_click(cx.listener(move |this, _, window, cx| this.new_story(window, cx)))
                .child(Icon::new(IconName::Plus).xsmall())
                .child("New story");
            column = column.child(gpui_kit::TestSupportExt::test_support(new_story));
        }
        column.into_any_element()
    }

    /// `element` as somewhere a dragged story can be dropped, at place `at`
    /// of `section`.
    fn drop_zone(
        &self,
        section: Section,
        at: usize,
        element: Stateful<Div>,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let gap = self.gap.clone();
        let shown = gap.get() == Some((section, at));
        element
            .relative()
            .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
                if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at))
                {
                    gap.set(Some((section, at)));
                    window.refresh();
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                this.gap.set(None);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(shown, |this| {
                this.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
    }

    fn render_mode_menu(
        &self,
        name: &str,
        mode: SendMode,
        highlighted: usize,
        cx: &mut Context<Self>,
    ) -> impl IntoElement + use<> {
        let theme = cx.theme().clone();
        let items = SendMode::ALL
            .into_iter()
            .enumerate()
            .map(|(at, choice)| {
                let name = name.to_string();
                h_flex()
