fn follower(handle: &Scroll, lock: &Option<(bool, SetLock)>) -> Option<Follow> {
    let (_, set_lock) = lock.as_ref()?;
    let (handle, set_lock) = (handle.clone(), set_lock.clone());
    Some(Rc::new(move |window, cx| {
        let max = handle.max_offset().y;
        if max > px(0.) {
            set_lock(at_bottom(&handle), window, cx);
        }
    }))
}

/// Whether the list is scrolled to its bottom, or past it before it is
/// clamped.
fn at_bottom(handle: &Scroll) -> bool {
    handle.offset().y <= -handle.max_offset().y + px(1.)
}

content.content:
1	//! A permanent scrollbar for a scrolling list, as a narrow column beside it:
2	//! a square button at the top that scrolls up, a track whose thumb shows how
3	//! much of the list is in view and can be dragged or clicked to, and a square
4	//! button at the bottom that scrolls down. Lists that follow new output, like
5	//! a task's, add a button below that locks the scroll to the bottom.
6	
7	use std::cell::Cell;
8	use std::rc::Rc;
9	use std::time::{Duration, Instant};
10	
11	use gpui_kit::component::{ActiveTheme as _, h_flex, v_flex};
12	use gpui_kit::prelude::FluentBuilder as _;
13	use gpui_kit::*;
14	
15	use crate::measured_list::MeasuredList;
16	
17	/// How wide the column is, which is also each button's width.
18	pub const COLUMN_WIDTH: Pixels = px(18.);
19	
20	/// How far a button scrolls the list.
21	const STEP: Pixels = px(48.);
22	
23	/// The shortest the thumb gets, so it can always be grabbed.
24	const MIN_THUMB: Pixels = px(16.);
25	
26	/// How long the pulse lasts when the scroll locks.
27	const PULSE_TIME: Duration = Duration::from_millis(900);
28	
29	/// What a scroll column scrolls: an element tracking a [`ScrollHandle`], or a
30	/// virtualized list that knows its rows' heights.
31	#[derive(Clone)]
32	pub enum Scroll {
33	    Handle(ScrollHandle),
34	    Measured(MeasuredList),
35	}
36	
37	impl From<&ScrollHandle> for Scroll {
38	    fn from(handle: &ScrollHandle) -> Self {
39	        Scroll::Handle(handle.clone())
40	    }
41	}
42	
43	impl From<&MeasuredList> for Scroll {
44	    fn from(list: &MeasuredList) -> Self {
45	        list.scroll()
46	    }
47	}
48	
49	impl Scroll {
50	    /// How far it is scrolled, negative going down.
51	    pub fn offset(&self) -> Point<Pixels> {
52	        match self {
53	            Scroll::Handle(handle) => handle.offset(),
54	            Scroll::Measured(list) => list.offset(),
55	        }
56	    }
57	
58	    /// How far it can scroll.
59	    pub fn max_offset(&self) -> Point<Pixels> {
60	        match self {
61	            Scroll::Handle(handle) => handle.max_offset(),
62	            Scroll::Measured(list) => list.max_offset(),
63	        }
64	    }
65	
66	    pub fn set_offset(&self, offset: Point<Pixels>) {
67	        match self {
68	            Scroll::Handle(handle) => handle.set_offset(offset),
69	            Scroll::Measured(list) => list.set_offset(offset),
70	        }
71	    }
72	
73	    /// The part of it in view.
74	    fn viewport(&self) -> Bounds<Pixels> {
75	        match self {
76	            Scroll::Handle(handle) => handle.bounds(),
77	            Scroll::Measured(list) => list.viewport(),
78	        }
79	    }
80	}
81	
82	/// The colours the column draws, each laid over whatever surface it sits on
83	/// rather than a colour of its own, so the scrollbar looks the same on any
84	/// surface: the raised parts, the line around the column, the buttons, and the
85	/// thumb, white laid over it; the single row at each end of the thumb, white
86	/// laid about half as far; the buttons' arrows, white laid over the buttons; and
87	/// the lightening of the thumb or a button while hovered and pressed. The
88	/// track has no fill at all: it is the surface.
89	#[derive(Clone, Copy, Debug, PartialEq)]
90	pub struct ScrollColors {
91	    pub raised: Hsla,
92	    pub thumb_end: Hsla,
93	    pub arrow: Hsla,
94	    pub hover: Hsla,
95	    pub pressed: Hsla,
96	}
97	
98	pub fn scroll_colors(dark: bool) -> ScrollColors {
99	    let (black, white) = (hsla(0., 0., 0., 1.), hsla(0., 0., 1., 1.));
100	    if dark {
101	        ScrollColors {
102	            // #222222 on #111111.
103	            raised: white.opacity(0.072),
104	            // #191919 on #111111, half way to the thumb.
105	            thumb_end: white.opacity(0.034),
106	            // #4d4d4d on the buttons' #222222.
107	            arrow: white.opacity(0.195),
108	            hover: white.opacity(0.035),
109	            pressed: white.opacity(0.07),
110	        }
111	    } else {
112	        // The mockup gives dark mode's; light mode raises the same way, as
113	        // its raised controls go lighter too, with the arrow darker rather
114	        // than lighter, as white would all but vanish on a light surface.
115	        ScrollColors {
116	            raised: white.opacity(0.35),
117	            thumb_end: white.opacity(0.17),
118	            arrow: black.opacity(0.35),
119	            hover: white.opacity(0.2),
120	            pressed: white.opacity(0.4),
121	        }
122	    }
123	}
124	
125	/// Locks the scroll to the bottom (`true`) or unlocks it (`false`).
126	pub type SetLock = Rc<dyn Fn(bool, &mut Window, &mut App)>;
127	
128	/// `content`, which scrolls with `handle`, beside its scroll column. With
129	/// `fill`, it fills the space it is given; otherwise it is as tall as
130	/// `content`, which is expected to cap its own height. With `lock`, whether
131	/// the scroll is locked to the bottom and how to switch it, the column ends in
132	/// a button for that; scrolling the list by hand, with the wheel or the
133	/// column, locks it when that leaves the list at the bottom and breaks the lock
134	/// when it doesn't.
135	pub fn with_scrollbar(
136	    id: impl Into<SharedString>,
137	    handle: impl Into<Scroll>,
138	    content: impl IntoElement,
139	    fill: bool,
140	    lock: Option<(bool, SetLock)>,
141	    cx: &App,
142	) -> AnyElement {
143	    let handle: Scroll = handle.into();
144	    let follow = follower(&handle, &lock);
145	    let row = h_flex()
146	        .items_stretch()
147	        .w_full()
148	        .when(fill, |row| row.flex_1().min_h_0().h_full())
149	        .child(
150	            div()
151	                .flex_1()
152	                .min_w_0()
153	                .when(fill, |it| it.h_full())
154	                // Scrolling by hand locks or unlocks the scroll. This bubbles
155	                // up from the list, which has already taken the scroll.
156	                .when_some(follow, |content, follow| {
157	                    content.on_scroll_wheel(move |_, window, cx| follow(window, cx))
158	                })
159	                .child(content),
160	        )
161	        .child(scrollbar(id.into(), &handle, lock, cx));
162	    row.into_any_element()
163	}
164	
165	/// `content`, which scrolls with `handle`, beside its scroll column, as tall
166	/// as `content` until the flex column it is in gives it less, when it shrinks
167	/// and `content` scrolls. `content` is expected to shrink too.
168	pub fn with_fitted_scrollbar(
169	    id: impl Into<SharedString>,
170	    handle: impl Into<Scroll>,
171	    content: impl IntoElement,
172	    cx: &App,
173	) -> AnyElement {
174	    let handle: Scroll = handle.into();
175	    h_flex()
176	        .items_stretch()
177	        .w_full()
178	        .flex_shrink(1.)
179	        .min_h_0()
180	        .child(v_flex().flex_1().min_w_0().min_h_0().child(content))
181	        .child(scrollbar(id.into(), &handle, None, cx))
182	        .into_any_element()
183	}
184	
185	/// After the list is scrolled by hand: locks the scroll when the list is left
186	/// at the bottom, and unlocks it when it isn't. A list with nothing to scroll
187	/// keeps its lock as it is.
188	type Follow = Rc<dyn Fn(&mut Window, &mut App)>;
189	
190	fn follower(handle: &Scroll, lock: &Option<(bool, SetLock)>) -> Option<Follow> {
191	    let (_, set_lock) = lock.as_ref()?;
192	    let (handle, set_lock) = (handle.clone(), set_lock.clone());
193	    Some(Rc::new(move |window, cx| {
194	        let max = handle.max_offset().y;
195	        if max > px(0.) {
196	            set_lock(at_bottom(&handle), window, cx);
197	        }
198	    }))
199	}
200	
201	/// Whether the list is scrolled to its bottom, or past it before it is
202	/// clamped.
203	fn at_bottom(handle: &Scroll) -> bool {
204	    handle.offset().y <= -handle.max_offset().y + px(1.)
205	}
206	
207	/// How tall each button is.
208	pub const BUTTON_HEIGHT: Pixels = px(17.);
209	
210	/// How far the track is inset from either side of the column.
211	const TRACK_INSET: Pixels = px(1.);
212	
213	/// The column itself: no background of its own, so its track is the colour of
214	/// whatever it sits on, with a line around it, the buttons, and the thumb
215	/// raised over that.
216	fn scrollbar(
217	    id: SharedString,
218	    handle: &Scroll,
219	    lock: Option<(bool, SetLock)>,
220	    cx: &App,
221	) -> AnyElement {
222	    let colors = scroll_colors(cx.theme().is_dark());
223	    let follow = follower(handle, &lock);
224	    let scroll_by = |delta: Pixels| {
225	        let handle = handle.clone();
226	        let follow = follow.clone();
227	        let press: Press = Rc::new(move |window: &mut Window, cx: &mut App| {
228	            let offset = handle.offset();
229	            let max = handle.max_offset().y;
230	            let y = (offset.y + delta).min(px(0.)).max(-max);
231	            handle.set_offset(point(offset.x, y));
232	            if let Some(follow) = &follow {
233	                follow(window, cx);
234	            }
235	            window.refresh();
236	        });
237	        press
238	    };
239	
240	    let track = canvas(
241	        // Where on the thumb it was grabbed, while it is being dragged. Kept
242	        // with the track from frame to frame, since each mouse move redraws
243	        // the column.
244	        |_, window, cx| {
245	            let grab = window
246	                .use_keyed_state("scroll-grab", cx, |_, _| Rc::new(Cell::new(None::<Pixels>)));
247	            // Whether the pointer was over the thumb when last drawn.
248	            let hovered =
249	                window.use_keyed_state("scroll-thumb-hover", cx, |_, _| Rc::new(Cell::new(false)));
250	            (grab, hovered)
251	        },
252	        {
253	            let handle = handle.clone();
254	            let follow = follow.clone();
255	            move |bounds,
256	                  (grab, hovered): (Entity<Rc<Cell<Option<Pixels>>>>, Entity<Rc<Cell<bool>>>),
257	                  window,
258	                  cx| {
259	                let grab = grab.read(cx).clone();
260	                let hovered = hovered.read(cx).clone();
261	                let geometry = Geometry::of(&handle, bounds);
262	                let thumb = thumb_bounds(&geometry, bounds);
263	                // The track is the surface, with the column's line down either
264	                // side of it, and the thumb raised across the column's full
265	                // width, the line and all, between its ends: a pixel at each
266	                // end, between the track's colour and the thumb's, across the
267	                // track. Nothing is laid twice.
268	                let (body, ends) = thumb_ends(thumb, bounds, &colors);
269	                for (top, bottom) in [(bounds.top(), body.top()), (body.bottom(), bounds.bottom())]
270	                {
271	                    for side in sides(bounds, top, bottom) {
272	                        window.paint_quad(fill(side, colors.raised));
273	                    }
274	                }
275	                window.paint_quad(fill(body, colors.raised));
276	                for (end, color) in ends {
277	                    window.paint_quad(fill(end, color));
278	                }
279	                // Lightening while hovered or dragged. Nothing is hovered
280	                // while something else, like a sidebar's edge, is being
281	                // dragged across it.
282	                let is_hovered = !cx.has_active_drag() && thumb.contains(&window.mouse_position());
283	                hovered.set(is_hovered);
284	                if grab.get().is_some() {
285	                    // No edge beneath the pointer is offered while dragging.
286	                    window.set_window_cursor_style(CursorStyle::Arrow);
287	                    window.paint_quad(fill(thumb, colors.pressed));
288	                } else if is_hovered {
289	                    window.paint_quad(fill(thumb, colors.hover));
290	                }
291	                // Moving on or off the thumb redraws it.
292	                window.on_mouse_event({
293	                    let (handle, hovered) = (handle.clone(), hovered.clone());
294	                    move |event: &MouseMoveEvent, _, window, _| {
295	                        let geometry = Geometry::of(&handle, bounds);
296	                        let thumb = thumb_bounds(&geometry, bounds);
297	                        if thumb.contains(&event.position) != hovered.get() {
298	                            window.refresh();
299	                        }
300	                    }
301	                });
302	
303	                window.on_mouse_event({
304	                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
305	                    move |event: &MouseDownEvent, phase, window, cx| {
306	                        if !bounds.contains(&event.position) {
307	                            return;
308	                        }
309	                        let geometry = Geometry::of(&handle, bounds);
310	                        let y = event.position.y;
311	                        // The thumb, or the track pressed off it, against any
312	                        // resize edge over it there: the smaller takes the
313	                        // press, taking it first when it is contested.
314	                        let on_thumb = y >= geometry.thumb_top
315	                            && y <= geometry.thumb_top + geometry.thumb_height;
316	                        let target = if on_thumb {
317	                            thumb_bounds(&geometry, bounds)
318	                        } else {
319	                            bounds
320	                        };
321	                        if !crate::hit_areas::wins_at(target, event.position, cx) {
322	                            return;
323	                        }
324	                        let contested = crate::hit_areas::resize_at(event.position, cx);
325	                        let turn = if contested {
326	                            DispatchPhase::Capture
327	                        } else {
328	                            DispatchPhase::Bubble
329	                        };
330	                        if phase != turn {
331	                            return;
332	                        }
333	                        if contested {
334	                            cx.stop_propagation();
335	                        }
336	                        // Grabbed where it was pressed; pressed off the thumb, the
337	                        // thumb first jumps to centre on the press.
338	                        let at = if on_thumb {
339	                            y - geometry.thumb_top
340	                        } else {
341	                            geometry.thumb_height / 2.
342	                        };
343	                        grab.set(Some(at));
344	                        geometry.scroll_thumb_to(&handle, y - at);
345	                        if let Some(follow) = &follow {
346	                            follow(window, cx);
347	                        }
348	                        window.refresh();
349	                    }
350	                });
351	                window.on_mouse_event({
352	                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
353	                    move |event: &MouseMoveEvent, _, window, cx| {
354	                        if let Some(at) = grab.get() {
355	                            if !event.dragging() {
356	                                grab.set(None);
357	                                return;
358	                            }
359	                            Geometry::of(&handle, bounds)
360	                                .scroll_thumb_to(&handle, event.position.y - at);
361	                            if let Some(follow) = &follow {
362	                                follow(window, cx);
363	                            }
364	                            window.refresh();
365	                        }
366	                    }
367	                });
368	                window.on_mouse_event({
369	                    let grab = grab.clone();
370	                    move |_: &MouseUpEvent, _, _, _| grab.set(None)
371	                });
372	            }
373	        },
374	    )
375	    .size_full();
376	
377	    let column = v_flex()
378	        .id(SharedString::from(format!("{id}-scroll-column")))
379	        .flex_none()
380	        .w(COLUMN_WIDTH)
381	        .child(square(
382	            format!("{id}-scroll-up"),
383	            Glyph::Up,
384	            "Scroll up".into(),
385	            false,
386	            scroll_by(STEP),
387	            None,
388	            colors,
389	        ))
390	        .child(gpui_kit::TestSupportExt::test_support(
391	            div()
392	                .id(SharedString::from(format!("{id}-scroll-track")))
393	                .flex_1()
394	                .min_h(px(8.))
395	                .child(track),
396	        ))
397	        .child(square(
398	            format!("{id}-scroll-down"),
399	            Glyph::Down,
400	            "Scroll down".into(),
401	            false,
402	            scroll_by(-STEP),
403	            None,
404	            colors,
405	        ))
406	        .when_some(lock, |column, (locked, set_lock)| {
407	            let press: Press = Rc::new(move |window, cx| set_lock(!locked, window, cx));
408	            let tooltip = if locked {
409	                "Unlock the scroll from the bottom"
410	            } else {
411	                "Lock the scroll to the bottom"
412	            };
413	            column
414	                // A pixel of the surface between it and the down button,
415	                // within the column's line.
416	                .child(
417	                    canvas(
418	                        |_, _, _| {},
419	                        move |bounds, _, window, _| {
420	                            for side in sides(bounds, bounds.top(), bounds.bottom()) {
421	                                window.paint_quad(fill(side, colors.raised));
422	                            }
423	                        },
424	                    )
425	                    .flex_none()
426	                    .w(COLUMN_WIDTH)
427	                    .h(LOCK_GAP),
428	                )
429	                .child(square(
430	                    format!("{id}-scroll-lock"),
431	                    Glyph::ToBottom,
432	                    tooltip.into(),
433	                    locked,
434	                    press,
435	                    Some(pulse(locked, cx).into_any_element()),
436	                    colors,
437	                ))
438	        });
439	    // Lets UI tests find the column; inert in normal builds.
440	    gpui_kit::TestSupportExt::test_support(column).into_any_element()
441	}
442	
443	/// The space between the down button and the lock button.
444	const LOCK_GAP: Pixels = px(1.);
445	
446	/// Where the track lies across a column at `bounds`: its left and its width,
447	/// a pixel in from either side.
448	fn inset(bounds: Bounds<Pixels>) -> (Pixels, Pixels) {
449	    (
450	        bounds.origin.x + TRACK_INSET,
451	        (bounds.size.width - TRACK_INSET * 2.).max(px(0.)),
452	    )
453	}
454	
455	/// The column's line down either side of a column at `bounds`, from `top` to
456	/// `bottom`: none where there is no height between them.
457	fn sides(bounds: Bounds<Pixels>, top: Pixels, bottom: Pixels) -> Vec<Bounds<Pixels>> {
458	    if bottom <= top {
459	        return Vec::new();
460	    }
461	    let height = bottom - top;
462	    vec![
463	        Bounds::new(point(bounds.left(), top), size(TRACK_INSET, height)),
464	        Bounds::new(
465	            point(bounds.right() - TRACK_INSET, top),
466	            size(TRACK_INSET, height),
467	        ),
468	    ]
469	}
470	
471	/// A thumb at `thumb`, in a track at `track`, split into the part raised
472	/// across the column's full width, and the single row at each end, across the
473	/// track's width, with its colour. With the thumb too short to have two ends,
474	/// all of it is raised.
475	fn thumb_ends(
476	    thumb: Bounds<Pixels>,
477	    track: Bounds<Pixels>,
478	    colors: &ScrollColors,
479	) -> (Bounds<Pixels>, Vec<(Bounds<Pixels>, Hsla)>) {
480	    let row = px(1.);
481	    if thumb.size.height < row * 2. {
482	        return (thumb, Vec::new());
483	    }
484	    let (left, width) = inset(track);
485	    let body = Bounds::new(
486	        point(thumb.left(), thumb.top() + row),
487	        size(thumb.size.width, thumb.size.height - row * 2.),
488	    );
489	    let ends = vec![
490	        (
491	            Bounds::new(point(left, thumb.top()), size(width, row)),
492	            colors.thumb_end,
493	        ),
494	        (
495	            Bounds::new(point(left, thumb.bottom() - row), size(width, row)),
496	            colors.thumb_end,
497	        ),
498	    ];
499	    (body, ends)
500	}
501	
502	/// What a button in the column shows: a small solid arrow, pointing up or
503	/// down, or down to a line for the lock.
504	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
505	pub(crate) enum Glyph {
506	    Up,
507	    Down,
508	    ToBottom,
509	}
510	
511	impl Glyph {
512	    /// The glyph's rows in a button at `bounds`, each as its top and width
513	    /// from the button's top, centred across it: a triangle 6 pixels wide
514	    /// and 4 tall, 7 pixels from the button's top pointing up or from its
515	    /// bottom pointing down, and for the lock the down arrow with a bar
516	    /// beneath it.
517	    fn rows(self) -> &'static [(f32, f32)] {
518	        match self {
519	            Glyph::Up => &[(7., 2.), (8., 4.), (9., 6.), (10., 6.)],
520	            Glyph::Down => &[(6., 6.), (7., 6.), (8., 4.), (9., 2.)],
521	            Glyph::ToBottom => &[(5., 6.), (6., 6.), (7., 4.), (8., 2.), (10., 6.)],
522	        }
523	    }
524	
525	    pub(crate) fn quads(self, bounds: Bounds<Pixels>) -> Vec<Bounds<Pixels>> {
526	        // Rounded to a whole pixel, so it stays crisp.
527	        let center = (bounds.origin.x + bounds.size.width / 2.).round();
528	        self.rows()
529	            .iter()
530	            .map(|&(top, width)| {
531	                Bounds::new(
532	                    point(center - px(width / 2.), bounds.origin.y + px(top)),
533	                    size(px(width), px(1.)),
534	                )
535	            })
536	            .collect()
537	    }
538	}
539	
540	/// A button in the column, `id`, as wide as the column and a button tall,
541	/// raised over the surface as the thumb is, showing `glyph`, with no bevel. It
542	/// lightens as the thumb does while hovered, and again while pressed with the
543	/// pointer still over it, or while `selected`. Pressing it does `press`.
544	/// `behind` is drawn beneath everything else in it.
545	fn square(
546	    id: String,
547	    glyph: Glyph,
548	    tooltip: SharedString,
549	    selected: bool,
550	    press: Press,
551	    behind: Option<AnyElement>,
552	    colors: ScrollColors,
553	) -> impl IntoElement {
554	    let arrow = canvas(
555	        |_, _, _| {},
556	        move |bounds, _, window, _| {
557	            for row in glyph.quads(bounds) {
558	                window.paint_quad(fill(row, colors.arrow));
559	            }
560	        },
561	    )
562	    .absolute()
563	    .top_0()
564	    .left_0()
565	    .size_full();
566	    let button = div()
567	        .id(SharedString::from(id.clone()))
568	        .relative()
569	        .flex_none()
570	        .w(COLUMN_WIDTH)
571	        .h(BUTTON_HEIGHT)
572	        .children(behind)
573	        .child(face(format!("{id}-face"), selected, colors))
574	        .child(arrow)
575	        .child(over_edges(format!("{id}-claim").into(), press.clone()))
576	        .tooltip(move |window, cx| {
577	            gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
578	        })
579	        .on_click(move |_, window, cx| press(window, cx));
580	    // Lets UI tests find the button; inert in normal builds.
581	    gpui_kit::TestSupportExt::test_support(button)
582	}
583	
584	/// A button's face: raised over the surface, lightened while hovered, and
585	/// again while pressed with the pointer still over it, or while `selected`.
586	/// It takes no mouse: it watches the mouse before the button does.
587	fn face(key: String, selected: bool, colors: ScrollColors) -> impl IntoElement {
588	    let key = SharedString::from(key);
589	    canvas(
590	        move |_, window, cx| {
591	            // Whether the button was pressed, and not yet let go.
592	            window.use_keyed_state(key, cx, |_, _| Rc::new(Cell::new(false)))
593	        },
