            }
            window.on_mouse_event({
                let claimed = claimed.clone();
                move |event: &MouseDownEvent, phase, window, cx| {
                    if phase == DispatchPhase::Capture
                        && event.button == MouseButton::Left
                        && contested(event.position, cx)
                    {
                        claimed.set(true);
