    let raised = crate::theme::color(crate::theme::palette(cx).raised);
    let card = v_flex()
        .id(SharedString::from(format!("planning-story-{name}")))
        .key_context(ROW_CONTEXT)
        .track_focus(&focus)
        .aria_label(title.clone())
        .group(group.clone())
        .relative()
        .w_full()
        .flex_none()
        .gap_1p5()
        .p_3()
        .rounded(px(6.))
        // Its line, and the focus ring on the card the keys work on.
        .border_1()
        .border_color(if focused { theme.ring } else { theme.border })
        .bg(if open { theme.list_active } else { raised })
        .cursor_pointer()
        .when(!open, |card| card.hover(|card| card.bg(theme.list_hover)))
        // Done, muted.
        .when(section == Section::Done, |card| card.opacity(0.6))
        .on_click(cx.listener(move |this, _, window, cx| {
            // A story sent opens its task; any other opens, or closes.
            this.focus_row(&click_name, window, cx);
            if let Some(task) = task.as_deref().filter(|_| !open) {
                (this.hooks.open_task)(task, window, cx);
            } else {
                this.toggle_story(&click_name, window, cx);
